/// <summary>
/// class <c>AVAKBVDirPartyContactPersonHelper</c>
/// </summary>
[DataContractAttribute]
class AVAKBVDirPartyContactPersonHelper
{
    //parameters
    DataAreaId          dataAreaId;
    DirPartyRecId       dirPartyId;
    DirPartyName        dirPartyName;
    ContactPersonName   contactPersonName;
    ContactPerson       contactPerson;
    ContactPersonId     contactPersonId;
    boolean             refresh;
    boolean             set;
    //variables
    ContactPersonId     contactPersonIdTmp;

}

