/// <summary>
/// get edit method for ContactPersonName
/// </summary>
/// <returns>ContactPersonName</returns>
public ContactPersonName  getEditContactPersonName()
{
    ContactPerson   locContactPerson;

    contactPersonIdTmp = contactPersonId;

    if (set)
    {
        if (contactPersonName)
        {
            changecompany(dataAreaId)
            {
                locContactPerson    = ContactPerson::find(contactPersonId);
                contactPersonIdTmp  = locContactPerson.ContactPersonId;

                if (contactPersonIdTmp)
                {
                    contactPersonName = locContactPerson.personName();
                }
                else
                {
                    DirPartyTable       partyTable;
                    DirPartyTable       forPartyTable;

                    select firstonly ContactPersonId
                    from locContactPerson
                    join forPartyTable
                    where locContactPerson.ContactForParty == forPartyTable.RecId
                        join    Name
                        from    partyTable
                        where   partyTable.RecId == locContactPerson.Party
                            &&  partyTable.Name  like contactPersonName;

                    if (locContactPerson.ContactPersonId)
                    {
                        contactPersonIdTmp  = locContactPerson.ContactPersonId;
                        contactPersonName   = partyTable.Name;
                    }
                }
                if (contactPersonId != contactPersonIdTmp)
                {
                    if (AVAKBVDirPartyContactPersonHelper::checkContactPersonOnDirPartyId(dirPartyId, contactPersonIdTmp))
                    {
                        refresh = true;
                    }
                    else
                    {
                        contactPersonIdTmp = contactPersonId;
                    }
                }
            }
        }
        else
        {
            contactPersonIdTmp = '';
        }
    }
    else
    {
        contactPersonName = AVAKBVDirPartyContactPersonHelper::contactPersonNameOnDataAreaId(contactPersonIdTmp, dataAreaId);
    }

    return contactPersonName;
}

/// <summary>
/// get edit method for ContactPersonName modified
/// </summary>
/// <returns>ContactPersonName</returns>
public ContactPersonName  getEditContactPersonNameModified()
{
    ContactPersonName   retVal;
    ContactPersonName   locContactPersonName;

    changecompany(dataAreaId)
    {
        if(dirPartyId && contactPersonName)
        {
            // Check if the input exists in ContactPerson.Name
            locContactPersonName = ContactPerson::find(contactPersonId).personName();
            // Set the contactPersonName with the ContactPerson.Name
            if (!locContactPersonName)
            {
                // Set the contactPersonName with the input text.
                locContactPersonName = contactPersonName;
            }

            if (!ContactPerson::findNameParty(dirPartyId, locContactPersonName))
            {
                contactPersonId = ContactPerson::findOrCreateNameParty(dirPartyId, contactPersonName).ContactPersonId;
            }
        }
        // fill name based on ContactPersonId
        if(contactPersonId)
        {
            locContactPersonName = ContactPerson::find(contactPersonId).personName();
        }
        else
        {
            locContactPersonName = '';
        }
        contactPersonName = locContactPersonName;


        dirPartyId      = AVAKBVDirPartyContactPersonHelper::checkGetDirPartyIdOnContactPersonId(dirPartyId, contactPersonId);
        dirPartyName    = DirPartyTable::findRec(dirPartyId).Name;
    }

    return retVal;
}

/// <summary>
/// method for ContactForParty value of associated contactPerson
/// </summary>
/// <param name = "_dirPartyId">DirPartyRecId</param>
/// <param name = "_contactPersonId">ContactPersonId</param>
/// <returns>DirPartyRecId</returns>
public static DirPartyRecId checkGetDirPartyIdOnContactPersonId(DirPartyRecId   _dirPartyId,
                                                                ContactPersonId _contactPersonId)
{
    DirPartyRecId   retVal;
    ContactPerson   locContactPerson;

    retVal              = _dirPartyId;
    locContactPerson    = ContactPerson::find(_contactPersonId);

    if (    locContactPerson.RecId
        &&  locContactPerson.ContactForParty
        &&  !_dirPartyId)
    {
        retVal = locContactPerson.ContactForParty;
    }

    return retVal;
}

/// <summary>
/// method to check if ContactPerson has a ContactPersonId, DirPartyId and if CustAccount for _dirpartyId equals CustAccount from ContactPerson
/// </summary>
/// <param name = "_dirPartyId">DirPartyRecId</param>
/// <param name = "_contactPersonId">ContactPersonId</param>
/// <param name = "_onCustomer">boolean</param>
/// <returns>boolean</returns>
public static boolean checkContactPersonOnDirPartyId(   DirPartyRecId   _dirPartyId,
                                                        ContactPersonId _contactPersonId,
                                                        boolean         _onCustomer = true )
{
    ContactPerson   locContactPerson;
    CustAccount     locCustAccount;

    if (_onCustomer)
    {
        locCustAccount  = CustTable::findByPartyRecId(_dirPartyId).AccountNum;
    }

    if (_contactPersonId)
    {
        locContactPerson = ContactPerson::find(_contactPersonId);

        if (!locContactPerson.ContactPersonId)
        {
            return false;
        }
        if (_dirPartyId && locContactPerson.ContactForParty != _dirPartyId)
        {
            return false;
        }
        if (_onCustomer && locCustAccount && locContactPerson.getCustAccount() != locCustAccount)
        {
            return false;
        }
    }
    return true;
}

/// <summary>
/// method to get name for ContactPerson for specified DataAreaId
/// </summary>
/// <param name = "_contactPersonId">ContactPersonId</param>
/// <param name = "_onDataAreaId">DataAreaId</param>
/// <returns>ContactPersonName</returns>
public static ContactPersonName contactPersonNameOnDataAreaId(ContactPersonId _contactPersonId, DataAreaId _onDataAreaId = '')
{
    if(_onDataAreaId != '')
    {
        changecompany(_onDataAreaId)
        {
            return ContactPerson::name(_contactPersonId);
        }
    }
    else
    {
        return ContactPerson::name(_contactPersonId);
    }
}

/// <summary>
///     AVA <c>lookupDirPartyCustAndOrOther</c> method.
/// </summary>
/// <param name="_control">
///     <c>FormReferenceControl</c> as type
/// </param>
/// <param name="_callerRecord">
///     <c>Common</c> as type
/// </param>
/// <param name="_includeCust">
///     <c>boolean</c> as type
/// </param>
/// <param name="_includeBusRel">
///     <c>boolean</c> as type
/// </param>
/// <param name="_includeComp">
///     <c>boolean</c> as type
/// </param>
/// <returns>
///     <c>Common</c> as return value
/// </returns>
public static Common lookupDirPartyCustAndOrOther(  FormReferenceControl    _control, 
                                                    Common                  _callerRecord, 
                                                    boolean                 _includeCust = true, 
                                                    boolean                 _includeBusRel = false, 
                                                    boolean                 _includeComp = false    )
{
    FormReferenceGroupControl       callingReferenceGroupControl;
    Common                          selectedRecord;
    dirPartyLookupEntitiesFilter    filter = dirPartyLookupEntitiesFilter::generateDirPartyLookupEntitiesFilter(NoYes::No);
    Args                            args;
    FormRun                         lookupForm;

    if (!_control)
    {
        throw(error(strFmt("@SYS137393", Error::wrongUseOfFunction(funcName())) ));
    }

    if(     _includeCust    == false
        &&  _includeBusRel  == false
        &&  _includeComp    == false)
    {
        _includeCust = true;
    }
    if(_includeCust == true)
    {
        filter.parmFilterCustomers(FilterStatus::Set);
    }
    if(_includeBusRel == true)
    {
        filter.parmFilterBusinessRelations(FilterStatus::Set);
    }
    if(_includeComp == true)
    {
        filter.parmFilterCompetitors(FilterStatus::Set);
    }

    args = new Args(formStr(DirPartyLookup));
    args.parmObject(filter);
    args.record(_callerRecord);
    args.caller(_control);

    lookupForm = classfactory.formRunClass(args);
    lookupForm.init();

    if (_control.handle() == classNum(FormReferenceGroupControl))
    {
        callingReferenceGroupControl = _control;
        callingReferenceGroupControl.performFormLookup(lookupForm);
        selectedRecord = lookupForm.selectRecordModeSelectedRecord();
    }

    return selectedRecord;
}

