/// <summary>
/// Look up DirPartyTable
/// </summary>
/// <param name = "_control">Object</param>
/// <param name = "_callerRecord">Common</param>
/// <returns>DirPartyTable</returns>
public static DirPartyTable lookupDirPartyRecId(Object _control, Common _callerRecord)
{
    DirPartyTable                   retVal;
    Common                          selectedRecord;
    dirPartyLookupEntitiesFilter    filter = dirPartyLookupEntitiesFilter::generateDirPartyLookupEntitiesFilter(NoYes::No);
    Args                            args;
    FormRun                         lookupForm;

    if (!_control)
    {
        throw(error(strFmt("@SYS137393", Error::wrongUseOfFunction(funcName())) ));
    }

    filter.parmFilterCompetitors(FilterStatus::Set);

    args = new Args(formStr(DirPartyLookup));
    args.parmObject(filter);
    args.record(_callerRecord);
    args.caller(_control);
    args.callerFormControl(_control);

    lookupForm = classfactory.formRunClass(args);
    lookupForm.init();

    _control.performFormLookup(lookupForm);
    selectedRecord = lookupForm.selectRecordModeSelectedRecord();

    retVal = selectedRecord;

    return retVal;
}
